const data = $input.first().json;

const systemPrompt = `Você é um consultor especialista em automação de processos para pequenas e médias empresas brasileiras, trabalhando para a agência mil&dez. Seu papel é analisar o contexto do negócio e gerar recomendações específicas e acionáveis de automação.

IMPORTANTE: Responda EXCLUSIVAMENTE em JSON válido, sem markdown, sem backticks, sem texto adicional. O JSON deve seguir exatamente esta estrutura:
{
  "workflows": [
    {
      "nome": "Nome do fluxo de automação",
      "ferramentas": "Lista das ferramentas envolvidas",
      "resultado": "Descrição concisa do resultado esperado",
      "tempo_economizado": "Estimativa de horas economizadas por semana"
    }
  ]
}

Gere exatamente 3 workflows. Seja específico para o setor e as ferramentas mencionadas. Use linguagem profissional mas acessível. Não use jargão técnico excessivo.`;

const userMessage = `Setor: ${data.setor}
Maior gargalo: ${data.gargalo}
Ferramentas atuais: ${data.ferramentas}
Empresa: ${data.empresa}

Gere 3 automações específicas para este negócio.`;

return [{
  json: {
    ...data,
    claudePayload: {
      model: "claude-sonnet-4-20250514",
      max_tokens: 1500,
      system: systemPrompt,
      messages: [{ role: "user", content: userMessage }]
    }
  }
}];

const claudeResponse = $input.first().json;
const text = claudeResponse.content[0].text;
const parsed = JSON.parse(text);
const wd = $('Webhook').first().json;

const cards = parsed.workflows.map((wf, i) => {
  const num = i + 1;
  return '<tr><td style="padding:8px 32px"><table width="100%" cellpadding="0" cellspacing="0" style="background:#274855;border-radius:6px"><tr><td style="padding:24px">'
    + '<p style="margin:0 0 8px;font-size:16px;font-weight:700;color:#fff">' + num + '. ' + wf.nome + '</p>'
    + '<p style="margin:0 0 4px;font-size:14px;color:#e0e0e0"><b style="color:#fff">Ferramentas:</b> ' + wf.ferramentas + '</p>'
    + '<p style="margin:0 0 4px;font-size:14px;color:#e0e0e0"><b style="color:#fff">Resultado:</b> ' + wf.resultado + '</p>'
    + '<p style="margin:8px 0 0;font-size:14px;color:#eb5100;font-weight:600">' + wf.tempo_economizado + ' economizados por semana</p>'
    + '</td></tr></table></td></tr>';
}).join('');

const emailHtml = '<!DOCTYPE html><html><head><meta charset="utf-8"></head>'
  + '<body style="margin:0;padding:0;background:#f8f7f4;font-family:Arial,sans-serif">'
  + '<table width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:0 auto;background:#fff">'
  + '<tr><td style="padding:32px;background:#085042;text-align:center">'
  + '<img src="https://miledez.com.br/logo.svg" alt="mil&dez" width="120"/>'
  + '</td></tr>'
  + '<tr><td style="padding:32px 32px 16px">'
  + '<p style="margin:0;font-size:18px;color:#274855;font-weight:600">Olá ' + wd.nome + ',</p>'
  + '<p style="margin:16px 0 0;font-size:16px;color:#4a4a4a;line-height:1.5">'
  + 'Analisamos o contexto da ' + wd.empresa + ' e preparamos recomendações de automação para o seu negócio.</p>'
  + '</td></tr>'
  + cards
  + '<tr><td style="padding:24px 32px;text-align:center">'
  + '<a href="https://wa.me/5531999999999" style="display:inline-block;padding:14px 28px;background:#eb5100;color:#fff;text-decoration:none;border-radius:6px;font-size:16px;font-weight:600">'
  + 'Agendar conversa gratuita</a></td></tr>'
  + '<tr><td style="padding:24px 32px;background:#f5f5f5;text-align:center">'
  + '<p style="margin:0;font-size:14px;color:#737373">mil&dez — Automação de Processos</p>'
  + '<p style="margin:4px 0 0;font-size:13px;color:#a3a3a3">Belo Horizonte, MG | miledez.com.br</p>'
  + '</td></tr></table></body></html>';

return [{
  json: {
    ...wd,
    workflows: parsed.workflows,
    resultado_ai: parsed,
    emailHtml: emailHtml
  }
}];
